import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final ListActiveLoansUseCase listActiveLoansUseCase;
    private final ListLoanHistoryUseCase listLoanHistoryUseCase;
    private final SuspendMemberUseCase suspendMemberUseCase;
    private final UnsuspendMemberUseCase unsuspendMemberUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            ListActiveLoansUseCase listActiveLoansUseCase,
                            ListLoanHistoryUseCase listLoanHistoryUseCase,
                            SuspendMemberUseCase suspendMemberUseCase,
                            UnsuspendMemberUseCase unsuspendMemberUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.listActiveLoansUseCase = listActiveLoansUseCase;
        this.listLoanHistoryUseCase = listLoanHistoryUseCase;
        this.suspendMemberUseCase = suspendMemberUseCase;
        this.unsuspendMemberUseCase = unsuspendMemberUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    @PostMapping("/{memberId}/suspend")
    public MemberResponse suspendMember(@PathVariable UUID memberId) {
        return MemberResponse.from(suspendMemberUseCase.suspendMember(memberId));
    }

    @PostMapping("/{memberId}/unsuspend")
    public MemberResponse unsuspendMember(@PathVariable UUID memberId) {
        return MemberResponse.from(unsuspendMemberUseCase.unsuspendMember(memberId));
    }

    @GetMapping("/{memberId}/loans")
    public ActiveLoanPageResponse listActiveLoans(@PathVariable UUID memberId,
                                                  @RequestParam(defaultValue = "0") int page,
                                                  @RequestParam(defaultValue = "20") int size) {
        return ActiveLoanPageResponse.from(
                listActiveLoansUseCase.listActiveLoans(new ListActiveLoansQuery(memberId, page, size)));
    }

    @GetMapping("/{memberId}/loans/history")
    public List<LoanHistoryResponse> listLoanHistory(@PathVariable UUID memberId) {
        return listLoanHistoryUseCase.listLoanHistory(memberId).stream()
                .map(LoanHistoryResponse::from)
                .toList();
    }
}
