package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class AuditLogIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loan_and_return_are_recorded_in_order_against_the_loan() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Clean Architecture");
        String loanId = loan(bookId, memberId);
        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("LOAN"))
                .andExpect(jsonPath("$[0].targetId").value(loanId))
                .andExpect(jsonPath("$[0].memberId").value(memberId))
                .andExpect(jsonPath("$[0].occurredAt").isString())
                .andExpect(jsonPath("$[1].action").value("RETURN"))
                .andExpect(jsonPath("$[1].targetId").value(loanId))
                .andExpect(jsonPath("$[1].memberId").value(memberId));
    }

    @Test
    void discard_is_recorded_against_the_book_with_null_member() throws Exception {
        String bookId = registerBook("Refactoring");
        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].action").value("DISCARD"))
                .andExpect(jsonPath("$[0].targetId").value(bookId))
                .andExpect(jsonPath("$[0].memberId").value((Object) null));
    }

    @Test
    void suspend_and_unsuspend_are_recorded_against_the_member_with_null_member() throws Exception {
        String memberId = registerMember();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("SUSPEND"))
                .andExpect(jsonPath("$[0].memberId").value((Object) null))
                .andExpect(jsonPath("$[1].action").value("UNSUSPEND"))
                .andExpect(jsonPath("$[1].memberId").value((Object) null));
    }

    @Test
    void rejected_loan_leaves_no_audit_record() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Domain-Driven Design");
        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk());
        mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"2026-02-02\"}"))
                .andExpect(status().isConflict());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void unknown_target_returns_empty_list() throws Exception {
        mockMvc.perform(get("/audit").param("targetId", "00000000-0000-0000-0000-000000000000"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    private String loan(String bookId, String memberId) throws Exception {
        return readId(mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"2026-02-02\"}")), "loanId");
    }

    private String registerMember() throws Exception {
        return readId(mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}")), "memberId");
    }

    private String registerBook(String title) throws Exception {
        return readId(mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}")), "id");
    }

    private String readId(ResultActions result, String field) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(body);
        return node.get(field).asText();
    }
}

