package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadAuditRecordPort;
import com.example.lending.application.port.out.SaveAuditRecordPort;
import com.example.lending.domain.AuditRecord;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class AuditRecordPersistenceAdapter implements SaveAuditRecordPort, LoadAuditRecordPort {

    private final AuditRecordJpaRepository auditRecordJpaRepository;
    private final AuditRecordMapper auditRecordMapper = new AuditRecordMapper();

    public AuditRecordPersistenceAdapter(AuditRecordJpaRepository auditRecordJpaRepository) {
        this.auditRecordJpaRepository = auditRecordJpaRepository;
    }

    @Override
    public void saveAuditRecord(AuditRecord auditRecord) {
        auditRecordJpaRepository.save(auditRecordMapper.toEntity(auditRecord));
    }

    @Override
    public List<AuditRecord> loadAuditRecordsByTargetId(UUID targetId) {
        return auditRecordJpaRepository.findByTargetIdOrderByOccurredAtAscIdAsc(targetId).stream()
                .map(auditRecordMapper::toDomain)
                .toList();
    }
}
